begin;
create extension if not exists pgtap with schema extensions;
select plan(8);
select set_config('request.jwt.claim.sub','92200000-0000-4000-8000-000000000099',true);
select set_config('request.jwt.claims','{"sub":"92200000-0000-4000-8000-000000000099","role":"authenticated"}',true);
create temp table entradas as select i-1 as indice, jsonb_build_object('indice',i-1,'marca','Nissan','modelo','Urvan Panel Diesel','condicion','seminueva','distanciaKm',10+i,'tiempoEstimadoHoras',1.5,'fechaHora','2026-10-18T18:00:00Z') as fila from generate_series(1,100) i;
create temp table individuales as select indice, public.usuario_previsualizar_tarifa('Nissan','Urvan Panel Diesel',(fila->>'distanciaKm')::numeric,1.5,'2026-10-18T18:00:00Z','seminueva') as cotizacion from entradas where indice < 30;
select throws_ok($$select public.usuario_previsualizar_tarifa('Nissan','Urvan Panel Diesel',20,1.5,'2026-10-18T18:00:00Z','seminueva')$$,'P0001','RATE_LIMITED','Reproduce el límite individual de 30 llamadas');
create temp table lote as select public.usuario_previsualizar_tarifas_masivas((select jsonb_agg(fila order by indice) from entradas)) as resultado;
select is((select jsonb_array_length(resultado) from lote),100,'Devuelve las 100 filas aunque se agotó el límite individual');
select is((select count(*)::int from lote,jsonb_array_elements(resultado) r where (r->>'disponible')::boolean),100,'Las 100 filas tienen cotización');
select is((select count(*)::int from individuales i,lote where (resultado->i.indice->>'tarifa')::numeric=(i.cotizacion->>'tarifa')::numeric),30,'Las tarifas coinciden al centavo con el wizard individual');
select ok((select (resultado->30->>'tarifa')::numeric > 0 and (resultado->99->>'tarifa')::numeric > 0 from lote),'Cotiza también las filas 31 y 100');
select throws_ok($$select public.usuario_previsualizar_tarifas_masivas((select jsonb_agg(fila) || jsonb_build_array(min(fila::text)::jsonb) from entradas))$$,'P0001','El lote debe contener entre 1 y 100 filas','Rechaza lotes mayores a 100');
select ok(not has_function_privilege('anon','public.usuario_previsualizar_tarifas_masivas(jsonb)','EXECUTE'),'No permite cotización anónima');
select public.usuario_previsualizar_tarifas_masivas(jsonb_build_array((select fila from entradas limit 1))) from generate_series(1,4);
select throws_ok($$select public.usuario_previsualizar_tarifas_masivas(jsonb_build_array((select fila from entradas limit 1)))$$,'P0001','RATE_LIMITED','Mantiene límite de cinco lotes por minuto');
select * from finish();
rollback;
